package com.aoo.bcg.matchmaking;

import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.h2.jdbcx.JdbcDataSource;
import org.junit.jupiter.api.*;
import java.time.*;
import java.util.*;

class JdbcCompetitionServiceTest {
 JdbcDataSource db;JdbcCompetitionService service;List<String> rewards;List<Map<String,Object>> roomRequests;
 @BeforeEach void setup()throws Exception{db=new JdbcDataSource();db.setURL("jdbc:h2:mem:mm;MODE=MySQL;DB_CLOSE_DELAY=-1");db.setUser("sa");try(var c=db.getConnection();var s=c.createStatement()){s.execute("DROP ALL OBJECTS");s.execute("CREATE TABLE aoo_sequence(sequence_name VARCHAR(64) PRIMARY KEY,next_value BIGINT NOT NULL)");s.execute("INSERT INTO aoo_sequence VALUES('aoo_match_seq',100),('aoo_room_seq',900)");s.execute("CREATE TABLE aoo_match_queue(player_id BIGINT,game_id BIGINT,play_version VARCHAR(64),state VARCHAR(24),enqueued_at TIMESTAMP,expires_at TIMESTAMP,match_id BIGINT,updated_at TIMESTAMP,PRIMARY KEY(player_id,game_id))");s.execute("CREATE TABLE aoo_compiled_index_active(game_id BIGINT,play_version VARCHAR(64))");s.execute("CREATE TABLE aoo_play_version(game_id BIGINT,play_version VARCHAR(64),status VARCHAR(16),activated_at TIMESTAMP)");s.execute("CREATE TABLE aoo_game_service_route(game_id BIGINT,play_version VARCHAR(64),status VARCHAR(16))");s.execute("INSERT INTO aoo_compiled_index_active VALUES(1,'v1'),(2,'v2')");s.execute("INSERT INTO aoo_play_version VALUES(1,'v1','ACTIVE',CURRENT_TIMESTAMP),(2,'v2','ACTIVE',CURRENT_TIMESTAMP)");s.execute("INSERT INTO aoo_game_service_route VALUES(1,'v1','ACTIVE'),(2,'v2','ACTIVE')");s.execute("CREATE TABLE aoo_match(match_id BIGINT PRIMARY KEY,game_id BIGINT,room_id BIGINT,room_route VARCHAR(1024),state VARCHAR(24),confirm_deadline TIMESTAMP,created_at TIMESTAMP)");s.execute("CREATE TABLE aoo_match_member(match_id BIGINT,player_id BIGINT,confirmed_at TIMESTAMP,PRIMARY KEY(match_id,player_id))");s.execute("CREATE TABLE aoo_tournament(tournament_id BIGINT PRIMARY KEY,game_id BIGINT,name VARCHAR(128),phase VARCHAR(24),updated_at TIMESTAMP)");s.execute("CREATE TABLE aoo_tournament_entry(tournament_id BIGINT,player_id BIGINT,status VARCHAR(24),registered_at TIMESTAMP,group_no INT,seed_no INT,score BIGINT DEFAULT 0,rank_no INT,PRIMARY KEY(tournament_id,player_id))");s.execute("CREATE TABLE aoo_competition_idempotency(player_id BIGINT,idempotency_key VARCHAR(128),operation VARCHAR(24),response_json CLOB,created_at TIMESTAMP,PRIMARY KEY(player_id,idempotency_key))");s.execute("CREATE TABLE aoo_competition_event(event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,player_id BIGINT,event_type VARCHAR(48),payload_json CLOB,created_at TIMESTAMP)");s.execute("INSERT INTO aoo_tournament VALUES(7,1,'Cup','REGISTRATION',CURRENT_TIMESTAMP)");}long[] nextRoom={900};rewards=new ArrayList<>();roomRequests=new ArrayList<>();service=new JdbcCompetitionService(db,(player,key,request)->{roomRequests.add(Map.copyOf(request));long roomId=++nextRoom[0];return Map.of("roomId",roomId,"route","hall://room/"+roomId);},(business,player,currency,amount,reason)->rewards.add(business+":"+player+":"+amount),Clock.fixed(Instant.parse("2026-08-24T00:00:00Z"),ZoneOffset.UTC),new ObjectMapper().findAndRegisterModules());}
 @Test void queueDuplicateCancelMatchAndConfirmAreClosed()throws Exception{assertEquals("WAITING",service.enqueue(1,"q1",1,60).get("state"));assertThrows(IllegalStateException.class,()->service.enqueue(1,"q2",1,60));var matched=service.enqueue(2,"q3",1,60);assertEquals("MATCHED",matched.get("state"));assertEquals("v1",roomRequests.getFirst().get("playVersion"));assertFalse(roomRequests.getFirst().containsKey("regionCode"));long match=((Number)matched.get("matchId")).longValue();assertEquals("PENDING_CONFIRM",service.confirm(1,"c1",match).get("state"));assertEquals("CONFIRMED",service.confirm(2,"c2",match).get("state"));assertEquals(service.confirm(2,"c2",match),service.confirm(2,"c2",match));assertThrows(IllegalStateException.class,()->service.cancel(1,"x",1));}
 @Test void opponentReceivesMatchPushAndRecoverySnapshotContainsRoute(){service.enqueue(21,"q21",2,60);service.enqueue(22,"q22",2,60);var events=service.events(21,0,100);assertTrue(events.stream().anyMatch(e->"MATCH_FOUND".equals(e.get("type"))));var snapshot=service.matchStatus(21,2);assertEquals("PENDING_CONFIRM",snapshot.get("state"));assertEquals("hall://room/901",snapshot.get("route"));}
@Test void rejectsIncompleteHallAuthorityResponseWithoutNullPointer(){var incomplete=new JdbcCompetitionService(db,(p,k,r)->Map.of("route","hall://missing-room"),(b,p,c,a,r)->{},Clock.fixed(Instant.parse("2026-08-24T00:00:00Z"),ZoneOffset.UTC),new ObjectMapper().findAndRegisterModules());incomplete.enqueue(41,"q41",1,60);IllegalStateException error=assertThrows(IllegalStateException.class,()->incomplete.enqueue(42,"q42",1,60));assertTrue(error.getMessage().contains("roomId"));}
 @Test void tournamentListAndRegistrationEventsAreAuthoritative(){assertEquals("NOT_REGISTERED",service.tournaments(31).getFirst().get("status"));service.register(31,"reg31",7);assertEquals("REGISTERED",service.tournaments(31).getFirst().get("status"));assertEquals("TOURNAMENT_REGISTERED",service.events(31,0,10).getFirst().get("type"));}
 @Test void cancelTimeoutTournamentGroupingRankingAndRewards()throws Exception{service.enqueue(3,"q",1,60);assertEquals("CANCELLED",service.cancel(3,"x",1).get("state"));service.enqueue(4,"timeout",1,60);var late=new JdbcCompetitionService(db,(p,k,r)->Map.of("route","hall://room"),(b,p,c,a,r)->{},Clock.fixed(Instant.parse("2026-08-24T00:02:00Z"),ZoneOffset.UTC),new ObjectMapper().findAndRegisterModules());assertEquals(1,late.expire());service.register(11,"r1",7);service.register(12,"r2",7);service.register(13,"r3",7);assertEquals(2,service.group(7,2).stream().map(x->x.get("group")).distinct().count());service.advance(7,11,50);service.advance(7,12,80);var ranking=service.rankAndReward(7,"GEM",List.of(100L,50L));assertEquals(12L,ranking.getFirst().get("playerId"));assertEquals(List.of("tournament-7-rank-1:12:100","tournament-7-rank-2:11:50"),rewards);}
}
